pts = [random.uniform(-2*math.pi, 2*math.pi) for _ in range(500)]
pts += [math.radians(d) for d in range(-360, 361, 5)]

results = {}
for name, f in candidates.items():
    results[name] = max(abs(orig(x) - f(x)) for x in pts)

matches = [n for n, e in results.items() if e < 1e-9]
if len(matches) == 1:
    final = matches[0]
    print(json.dumps({
        "final_answer": final,
        "evidence": {"points_tested": len(pts), "max_abs_error": results[final]}
    }))
