import math, json
from fractions import Fraction

s3 = math.sqrt(3)
def m(x): return (s3*math.sin(x), math.sin(x))
def n(x): return (math.cos(x), math.sin(x))
def cross(x):
    a, b = m(x), n(x)
    return a[0]*b[1] - a[1]*b[0]
def f(x):
    a, b = m(x), n(x)
    return a[0]*b[0] + a[1]*b[1]
def fp(x, h=1e-6):
    return (f(x+h) - f(x-h)) / (2*h)

def frac_pi(v, den=12):
    return Fraction(round(v/math.pi*den), den)

def show(fr):
    if fr == 0:
        return "0"
    s = "" if fr > 0 else "-"
    fr = abs(fr)
    num = "pi" if fr.numerator == 1 else f"{fr.numerator}pi"
    return s + (num if fr.denominator == 1 else f"{num}/{fr.denominator}")

# Part 1: roots of cross product on [0, pi/2]
N = 20000
lo, hi = 0.0, math.pi/2
roots = []
if abs(cross(lo)) < 1e-12:
    roots.append(lo)
if abs(cross(hi)) < 1e-12:
    roots.append(hi)
for i in range(N):
    a = lo + (hi-lo)*i/N
    b = lo + (hi-lo)*(i+1)/N
    ca, cb = cross(a), cross(b)
    if ca*cb < 0:
        for _ in range(100):
            mid = (a+b)/2
            if cross(a)*cross(mid) <= 0:
                b = mid
            else:
                a = mid
        roots.append((a+b)/2)
# interior roots only counted once; dedupe
uniq = []
for r in sorted(roots):
    if not uniq or abs(r-uniq[-1]) > 1e-6:
        uniq.append(r)
root_fracs = [frac_pi(r) for r in uniq]
part1 = [show(fr) for fr in root_fracs]
ok1 = all(abs(cross(float(fr)*math.pi)) < 1e-9 for fr in root_fracs)

# Part 2: smallest positive period among multiples of pi/12
samples = [-3 + 0.37*k for k in range(40)]
period = None
for j in range(1, 49):
    p = math.pi*j/12
    if all(abs(f(x+p)-f(x)) < 1e-9 for x in samples):
        period = Fraction(j, 12)
        break

# Increasing intervals: sign changes of derivative over one period starting at -pi/2
start = -math.pi/2
L = float(period)*math.pi
M = 40000
changes = []
prev = fp(start + 1e-9)
for i in range(1, M+1):
    x = start + L*i/M
    cur = fp(x)
    if prev*cur < 0:
        changes.append((x, cur > 0))
    prev = cur
inc_start = None
inc_end = None
for x, rising in changes:
    if rising and inc_start is None:
        inc_start = frac_pi(x)
    if (not rising) and inc_end is None:
        inc_end = frac_pi(x)
# make sure start < end
if inc_start is not None and inc_end is not None and inc_end < inc_start:
    inc_end = inc_end + period
# verify increasing on found interval, decreasing outside
a, b = float(inc_start)*math.pi, float(inc_end)*math.pi
chk_in = all(fp(a + (b-a)*t/100) > 0 for t in range(1, 100))
chk_out = all(fp(b + (L-(b-a))*t/100) < 0 for t in range(1, 100))

if (not ok1 or period is None or inc_start is None or inc_end is None
        or not chk_in or not chk_out):
    print("UNSUPPORTED")
else:
    k = "k"
    interval = f"[{show(inc_start)} + k*pi, {show(inc_end)} + k*pi], k in Z"
    final = (f"(1) x = {part1[0]} or x = {part1[1]}; "
             f"(2) f(x) = sin(2x - pi/6) + 1/2, smallest positive period {show(period)}, "
             f"increasing on {interval}")
    print(json.dumps({
        "final_answer": final,
        "evidence": {
            "part1_roots": part1,
            "period_over_pi": str(period),
            "increasing_interval_one_period": [show(inc_start), show(inc_end)],
            "checks": [ok1, chk_in, chk_out]
        }
    }))
```

