import json, math

def g(a, x):
    # log of ((1/x)*(a^x-1)/(a-1)) divided by x, computed stably; a>0, a!=1
    if a == 1:
        return 0.0 - math.log(1) / x + (math.log(x) - math.log(x)) / x
    if a > 1:
        L = x * math.log(a) + math.log1p(-math.exp(-x * math.log(a))) - math.log(a - 1)
    else:
        L = math.log1p(-math.exp(x * math.log(a))) - math.log(1 - a)
    L -= math.log(x)
    return math.exp(L / x)

evidence = {}
for a in [0.25, 0.5, 0.9, 1, 1.5, 2, 3, 10]:
    x = 10**7
    val = g(a, x)
    predicted = max(1.0, a)
    evidence[str(a)] = {"value_at_x=1e7": val, "predicted": predicted,
                        "abs_err": abs(val - predicted)}

ok = all(v["abs_err"] < 1e-4 for v in evidence.values())
out = {
    "final_answer": "max(1, a) for a>0: the limit is a if a>1, and 1 if 0<a<=1" if ok else "UNSUPPORTED",
    "evidence": evidence,
}
print(json.dumps(out))
