from fractions import Fraction as F
import math

def attained(v):
    # v is in range iff some integer n has x = n^2 - v with floor(x) = n
    # for |n| > 50 and |v| < 2500, x = n^2 - v is far from [n, n+1) only when n^2 is large; bound is safe
    for n in range(-100, 101):
        x = n * n - v
        if n <= x < n + 1:
            return True
    return False

def claimed(v):
    if -1 <= v <= 0:
        return True
    for n in range(2, 200):
        if n*n - n - 1 < v <= n*n - n:
            return True
    return False

# check g directly at x = 1, 2 (sanity) and the value -1
print("g values near -1:")
for x in [F(0), F(1,2), F(99,100), F(1), F(2)]:
    print(" x =", x, " g =", math.floor(x)**2 - x)

print("Is -1 attained? ", attained(F(-1)))
print("Claimed set contains -1? ", claimed(F(-1)))

# compare on a grid of rationals (sampling check)
mismatches = []
for k in range(-40, 12*40):
    v = F(k, 20)
    if attained(v) != claimed(v):
        mismatches.append((v, attained(v), claimed(v)))
print("mismatches (value, actually attained, claimed):", mismatches[:10])

# exact claim: range = (-1,0] U union_{n>=2}(n^2-n-1, n^2-n]
if mismatches:
    print("CHECK FAIL: submitted answer wrongly includes -1 (the left endpoint should be open).")
else:
    print("CHECK PASS")
