import math

# Problem II.8.79's statement is not given, so the definitions of Z_alpha and Y_alpha
# cannot be checked. This script verifies only what can be computed independently.

def simpson(f, a, b, n=200000):
    if n % 2:
        n += 1
    h = (b - a) / n
    s = f(a) + f(b)
    for i in range(1, n):
        s += f(a + i * h) * (4 if i % 2 else 2)
    return s * h / 3

# 1) Check the Levy formula numerically: int e^{-lam t} a e^{-a^2/2t}/sqrt(2 pi t^3) dt = e^{-a sqrt(2 lam)}
def levy_density(t, a):
    if t <= 0:
        return 0.0
    return a * math.exp(-a * a / (2 * t)) / math.sqrt(2 * math.pi * t ** 3)

levy_ok = True
for a, lam in [(1.0, 1.0), (2.0, 0.5), (0.7, 2.0)]:
    num = simpson(lambda t: math.exp(-lam * t) * levy_density(t, a), 0.0, 60.0 / lam, 400000)
    exact = math.exp(-a * math.sqrt(2 * lam))
    print("Levy a=%.2f lam=%.2f numeric=%.6f exact=%.6f" % (a, lam, num, exact))
    if abs(num - exact) > 1e-3:
        levy_ok = False

# So Laplace transform e^{-alpha sqrt(2 lam)} corresponds to density alpha e^{-alpha^2/2t}/sqrt(2 pi t^3).
print("Levy formula numerically consistent:", levy_ok)

# 2) Internal consistency of submitted (b): density sqrt(2/pi) t^{-1/2} e^{-2t} vs erf(sqrt(2y))
# Substituting t = v^2 removes the singularity: integrand becomes 2 sqrt(2/pi) e^{-2 v^2} dv.
def cdf_from_density(y):
    return simpson(lambda v: 2 * math.sqrt(2 / math.pi) * math.exp(-2 * v * v), 0.0, math.sqrt(y), 20000)

cons_ok = True
for y in [0.1, 0.5, 1.0, 2.0, 5.0]:
    c = cdf_from_density(y)
    e = math.erf(math.sqrt(2 * y))
    print("y=%.1f integral=%.8f erf(sqrt(2y))=%.8f" % (y, c, e))
    if abs(c - e) > 1e-8:
        cons_ok = False
print("Submitted CDF matches its own stated density:", cons_ok)

# 3) The density of Y_2 itself (what Y_alpha is) cannot be derived without the problem statement.
print("Density/definition of Y_alpha from Problem II.8.79 is not available; cannot confirm the density used in (b).")
print("Part (a) Z_alpha density matches the Levy formula inversion (if Z_alpha has Laplace transform e^{-alpha sqrt(2 lam)}).")
print("CHECK UNKNOWN")
