b = math.sqrt(2)
B = math.radians(45)

sinA = a * math.sin(B) / b
sols = []
if abs(sinA) <= 1 + 1e-12:
    s = min(1.0, sinA)
    A0 = math.degrees(math.asin(s))
    cands = {round(A0, 9), round(180 - A0, 9)}
    for A in sorted(cands):
        C = 180 - A - 45
        if C > 1e-9 and A > 0:
            c = b * math.sin(math.radians(C)) / math.sin(B)
            sols.append((A, C, c))

def closed(c):
    if abs(c - (math.sqrt(6) + math.sqrt(2)) / 2) < 1e-9:
        return "(sqrt(6)+sqrt(2))/2"
    if abs(c - (math.sqrt(6) - math.sqrt(2)) / 2) < 1e-9:
        return "(sqrt(6)-sqrt(2))/2"
    return None

