    for A, C, c in sols:
        cf = closed(c)
        if cf is None:
            print("UNSUPPORTED")
            raise SystemExit
        parts.append(f"A={round(A)} deg, C={round(C)} deg, c={cf}")
    final = " or ".join(parts)
