import json

# Rules derived from the data (Proto-Chamic -> Phan Rang Cham):
# 1. Initial voiced stop devoices: d->t, b->p, j->c.
# 2. A voiced-stop initial (d, b, j) puts a grave accent on the vowel of the
#    final syllable (dilah->talàh, jalaːn->calàn, padam->patàm).
# 3. Final -m, -h and -n are kept (padam->patàm, masam->mɨtham).
# 4. Word-final -k and -t become -ʔ (not relevant for *dalam).
# 5. The first-syllable vowel of *dalam is a, kept as in *dalam-type forms
#    (jalaːn->calàn, dilah->talàh).

def derive(proto):
    devoice = {"d": "t", "b": "p", "j": "c"}
    first = proto[0]
    out = list(proto.replace("ː", ""))
    voiced_initial = first in devoice
    if first in devoice:
        out[0] = devoice[first]
    if voiced_initial:
        grave = {"a": "à", "i": "ì", "u": "ù", "o": "ò", "e": "è"}
        for i in range(len(out) - 1, -1, -1):
            if out[i] in grave:
                out[i] = grave[out[i]]
                break
    return "".join(out)

proto = "dalam"
answer = derive(proto)
print(json.dumps({
    "final_answer": answer,
    "evidence": {
        "item": 10,
        "proto": "*dalam",
        "rules": ["initial d->t", "grave on final vowel after voiced initial stop", "final m retained"],
        "parallels": {"*padam": "patàm", "*dilah": "talàh", "*jalaːn": "calàn"}
    }
}, ensure_ascii=False))
