    "*": lambda a, b: a*b,
    "!": excl, ":": colon, "~": tilde, "#": hashop,
    "<>": diamond, "][": brk,
}

def apply(opstr, a, b):
    parts = re.findall(r'<>|\]\[|[-+*!:~#]', opstr)
    assert "".join(parts) == opstr, opstr
    r = OPS[parts[0]](a, b)
    for p in parts[1:]:
        r = OPS[p](r, b)
    return r

def is_atom(t):
    return re.fullmatch(r'-?\d+', t) is not None or t in W

def atomval(t):
    return W[t] if t in W else int(t)

def evaluate(s):
